+/* Find an exact physical node boundary. The physical walk has already
+ * validated the heap before this helper is used for a free-list pointer. */
+static bool agent_heap_gate_find_physical_node(
+    const struct mm_heap_s *heap, uintptr_t target,
+    bool *is_free, int *region_out, size_t *size_out)
+{
+    int regions = agent_heap_gate_region_count(heap);
+    int region;
+
+    if (target == 0 || (target & (MM_ALIGN - 1)) != 0 ||
+        regions <= 0 || regions > CONFIG_MM_REGIONS) {
+        return false;
+    }
+
+    for (region = 0; region < regions; region++) {
+        uintptr_t start = (uintptr_t)heap->mm_heapstart[region];
+        uintptr_t end = (uintptr_t)heap->mm_heapend[region];
+        uintptr_t address = start;
+        size_t steps = 0;
+        size_t max_steps;
+
+        if (start == 0 || end <= start) {
+            return false;
+        }
+
+        max_steps = (end - start) / MM_SIZEOF_ALLOCNODE;
+        if (max_steps == SIZE_MAX) {
+            return false;
+        }
+        max_steps++;
+
+        while (address < end) {
+            size_t remaining = end - address;
+            struct mm_allocnode_s *node;
+            size_t size;
+
+            if (steps >= max_steps) {
+                return false;
+            }
+            steps++;
+
+            if (remaining < MM_SIZEOF_ALLOCNODE ||
+                (address & (MM_ALIGN - 1)) != 0) {
+                return false;
+            }
+
+            node = (struct mm_allocnode_s *)address;
+            size = MM_SIZEOF_NODE(node);
