+                *is_free = MM_NODE_IS_FREE(node);
+                *region_out = region;
+                *size_out = size;
+                return true;
+            }
+
+            address += size;
+        }
+
+        if (address != end && target < end) {
+            return false;
+        }
+    }
+
+    return false;
+}
